p='users.js'
s=open(p).read()
s=s.replace('''// GET /orders''','''// GET /v2/users: same list with snake_case field names, matching /orders.
// /users keeps userId until its consumers have moved over.
function listUsersV2(req, res) {
  res.json(
    users.map((u) => ({ user_id: u.id, name: u.name, email: u.email })),
  );
}

// GET /orders''')
s=s.replace('module.exports = { listUsers, listOrders };','module.exports = { listUsers, listUsersV2, listOrders };')
open(p,'w').write(s)
EOF
